  (240, '2025-04-04', '21:15:00', 1, 1, 'Main Stage', 'Completed', '"Sister Act" FNL: two pairs of sisters (Alice and Lili, Gigi and Sam), 80% related cast, cold open of dueling good/evil Fairy Tale Twins. Jeff on bar (and One Hot Hour). Sam''s second show. Show recorded by Ferdi. Same list as the Apr 2 cast-wide email.', false, 'standard'),
  (241, '2025-04-05', '20:30:00', 2, 15, 'Main Stage', 'Completed', 'BIG SHOW: KC''s return to directing ("KC Masterpiece"). Replaces the Apr 2 cast-wide email, which listed crew only as Jeff and Mike A. with tech needed. KC sent the line-up PDF day-of, call time 7:30pm.', false, 'standard'),
  (242, '2025-04-11', '23:00:00', 1, 2, 'Main Stage', 'Completed', 'Replaces the Apr 9 list (Matthew moved from Tech into the cast, Sam added on Tech). Rick U. sent the lineup PDF day-of ("FNL April 11 6person"), new pieces, call 7:30pm. Same night: One Hot Hour 8pm, Stand Up Student Show 9:30pm (Rick M. with Michelle), DeathMatch 11pm (no cast list found).', false, 'standard'),
  (243, '2025-04-12', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'Replaces the Apr 9 list (Diana, Alex T., Rick M., Rick U.; Tech TBA): Rick U. moved to Tech (if no other tech found), David H. and Yvette added. Diana sent the lineup PDF day-of (TBS_Apr12), meet 7:45pm. Same night 2 Up at 8pm in the Spotlight, which Jeff says he directed with a small crew.', false, 'standard'),
  (244, '2025-04-18', '21:15:00', 1, 12, 'Main Stage', 'Completed', 'Matthew''s directorial debut (assisted by Diana) and Jeff''s long overdue Mainstage debut. Adrian came down to play. Replaces the Apr 16 cast-wide email (which lacked Adrian and had Heidi with a question mark). Matthew (Christopher Miranda) sent the set list Apr 17. The JTF Presents spot that Friday was still open on Apr 16.', false, 'standard'),
  (245, '2025-04-19', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'BIG SHOW: Second City''s Russ Gooberman as visiting guest (written "Russ Gooberman Visiting Guest)"), after his afternoon workshop. Replaces the Apr 16 cast-wide email (same cast; Jeff on Bar and 2 Up had a question mark).', false, 'standard'),
  (246, '2025-04-25', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Replaces the Apr 23 cast-wide email (which had Alice on Tech and Ferdi as plain cast). Rick U. on tech arriving late around 8:15pm. Setlist by Jarrett and Ferdi; Ferdi sent notes May 1. Larger cast, costumes and props; the email calls it "Jarrett''s big show".', false, 'standard'),
  (247, '2025-04-26', '20:30:00', 2, 12, 'Main Stage', 'Completed', 'BIG SHOW: Replaces the Apr 23 cast-wide email (Tech was TBA there). Matthew circulated the set list Apr 25; Rebecca made a show image. Michelle running Stand Up Miami in the Spotlight closed up.', false, 'standard'),
  (248, '2025-05-02', '23:00:00', 1, 8, 'Main Stage', 'Completed', 'Michelle''s FNL. Cast from Apr 30 email; crew finalized May 1 (Alex T. on Tech, replacing TBA). Replaces the Apr 30 cast-wide email. DeathMatch at 11pm same night (no cast list found).', false, 'standard'),
  (249, '2025-05-03', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'Cheap Trills: Musical improv with Carol on the keys. Day-of list from Rick U. (dress up a bit). Replaces Rick M.''s Apr 30 lists (same cast, written Rick U. (Director), David H., Rick M.; crew Tech TBA, Box TBA, Bar & 2 Up Jocelyn). Jeff volunteered to box.', false, 'standard'),
  (250, '2025-05-09', '21:15:00', 1, 4, 'Main Stage', 'Completed', 'Fleshed out after Wednesday rehearsal: Christoph added to cast, Kim (Tech) and Dave P. (Box) added. Replaces the May 6 and May 7 lists (Tech and Box TBA). First JTF Presents in the Spotlight at 9:30pm the same night (act not named).', false, 'standard'),
  (251, '2025-05-09', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Milk and Cookies: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (252, '2025-05-10', '20:30:00', 2, 13, 'Main Stage', 'Completed', 'BIG SHOW: Sammi directing. Only the cast-wide listing was found (Tech still needed); no later update in Jeff''s mail. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (253, '2025-05-16', '21:15:00', 1, 7, 'Main Stage', 'Completed', 'Lili''s directing debut. Dom''s first Mainstage show. Xavier''s first crew spot. Preliminary cast (directors could add at rehearsal); no later FNL update found. Sent twice the same morning with near-identical text (other copy thread 196cf83aadde1b57).', false, 'standard'),
  (254, '2025-05-17', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'BIG SHOW: Jeff''s first Big Show listing. Replaces the May 14 cast-wide email (Tech and House TBA). Jarrett''s day-of setlist email (thread 196e05379bcd4c6d) also went to Mike A. and Alex T., who may have been added to the cast; the setlist PDF could not be read, so they are not listed here.', false, 'standard'),
  (255, '2025-05-23', '21:15:00', 1, 15, 'Main Stage', 'Completed', 'Special guest JD Walsh (written "JD (Guest)"), back after playing with the cast two summers ago (Two and a Half Men pizza delivery man). JTF Presents slot still free that night. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (256, '2025-05-24', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'BIG SHOW: Memorial Day weekend. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (257, '2025-05-30', '21:15:00', 1, 9, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (258, '2025-05-30', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Side Quest!: Dungeons & Dragons improv act; Matthew requested the 5/30 JTF Presents Spotlight slot on May 5 and updated the spreadsheet. Jeff confirmed it ran and that he played (2026-11-07); the booking sheet lists the same players.', true, 'jtf_presents'),
  (259, '2025-05-31', '20:30:00', 2, 14, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (260, '2025-06-06', '21:15:00', 1, 19, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (261, '2025-06-07', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (262, '2025-06-13', '21:15:00', 1, 8, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (263, '2025-06-13', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'There''s Something about Harry: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (264, '2025-06-14', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (265, '2025-06-20', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (266, '2025-06-20', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Clutch & Friends: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (267, '2025-06-21', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (268, '2025-06-27', '21:15:00', 1, 12, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (269, '2025-06-28', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (270, '2025-07-05', '20:30:00', 2, 14, 'Main Stage', 'Completed', 'Second City''s Jorge Berrios as guest (written "Jorge Berrios (Guest)"), after his sold-out afternoon workshop ("Out of Your Head, Into Your Body"). Final list from the Jul 4 cast-wide email; replaces Jul 1 (Matthew in cast, Dom on crew) and Jul 3 (Matthew dropped, Alex T. added as Tech). Ferdi sent the setlist day-of and show notes Jul 10.', false, 'standard'),
  (271, '2025-07-11', '21:15:00', 1, 15, 'Main Stage', 'Completed', 'Christoph''s final apprentice crew duty. Same night in the Spotlight: stand up student showcase 7pm and JTF Presents David Magnifico 9:30pm (long overdue return). Bartender still needed. Email is an update; no earlier listing found. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (272, '2025-07-11', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'David Magnifico: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (273, '2025-07-12', '20:30:00', 2, 19, 'Main Stage', 'Completed', 'BIG SHOW: Mark may have added to his cast at the Wednesday rehearsal split (no later list found). Same night: 2 Up 8pm and Stand Up Miami: The Karaoke Edition 9:30pm in the Spotlight. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (274, '2025-07-18', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (275, '2025-07-18', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', '69 Minutes of Double Entendre: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (276, '2025-07-19', '20:30:00', 2, 13, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (277, '2025-07-23', '20:30:00', 11, NULL, 'Main Stage', 'Completed', 'Private corporate show: Private corporate show Wednesday afternoon for DataRemote (telecommunications company), about 20 to 25 people, call time 12:30pm, done by 2:45pm. Organized by Rick U. (lineup PDF "Private Show 3 person July 23"); performers paid by Rick M. via Zelle.', true, 'standard'),
  (278, '2025-07-25', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Preliminary list; Bar and House still TBA. No later update found. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (279, '2025-07-26', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'CHEAP TRILLS: Preliminary list. Cheap Trills cast must have completed the Musical Improv class (the only 9pm Mainstage show requiring a grad-level class). Another Cheap Trills planned two Saturdays later. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (280, '2025-08-01', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Acting for Improvisers: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (281, '2025-08-01', '23:00:00', 1, 9, 'Main Stage', 'Completed', 'Oscar directing. Jul 28 email said FNL was wide open with only Alvin and Rick M. signed up. Same night: Adrian in One Hot Hour 8pm, DeathMatch 11pm, and JTF Presents student showcase of Mark''s Improv for Actors class 9:30pm.', false, 'standard'),
  (282, '2025-08-02', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'BIG SHOW: Dating-show theme (Love Machine bachelors with character bios and theme songs). Dominic''s Big Show debut; Mike A.''s birthday (he promoted the show). SOLD OUT: 50 presales. Final list from Rick''s Jul 31 email (quoted in replies; the original is not in Jeff''s mailbox); replaces the Jul 29 list, which also had Lucy and Matthew in the cast and Libby on Box with no House or Bar. Diana sent lineup xlsx day-of.', false, 'standard'),
  (283, '2025-08-08', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Special guest Lisa Lynn (touring UK improviser, founder of Acaprov) all week: ran Wednesday rehearsal, played FNL and Saturday, taught two workshops Aug 9. Lizzie completed her crew duties on this night. Some cast away at the Countdown Festival that weekend.', false, 'standard'),
  (284, '2025-08-09', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'Cheap Trills: Listed under the heading BIG SHOW CAST but this Saturday was the Cheap Trills musical improv show (Rick U. directing, per Jul 31 and Aug 11 emails) with guest Lisa Lynn. Rick U is listed first without a (Director) tag. Lizzie''s first Cheap Trills. Michael T. bartended Saturday (per Aug 11 recap). Tech still needed at time of email.', false, 'standard'),
  (285, '2025-08-15', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Theme: "The Event - Alien Invasion Edition" with a Town Hall opening (Rick made a promo). Stefany''s tech debut. Replaces the Aug 12 cast-wide email (which had Emanuel on Box and Gigi on House; Aug 11 email had listed Friday crew as Stefany, Gigi and Emanuel). Rick sent the setlist day-of. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (286, '2025-08-16', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'BIG SHOW: Replaces the Aug 12 cast-wide email (Rick M. on Tech, "Maybe Jeff" on Bar and 2 Up). Rick U.''s day-of lineup email (thread 198b42782288b4c7) also went to Dave R. (Dave Reynolds) and Valentino, who were likely added to the cast (lineup attachment not readable). Libby completed her eighth crew spot this Saturday (position not listed).', false, 'standard'),
  (287, '2025-08-22', '21:15:00', 1, 14, 'Main Stage', 'Completed', 'Possibly Mark''s (Mocahbee) last JTF show until next summer; he is leaving to teach abroad for the school year. Listed as currently slated.', false, 'standard'),
  (288, '2025-08-23', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'BIG SHOW: Lili directing. Listed as currently slated; no later update found. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (289, '2025-08-29', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Side Quest 2: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (290, '2025-08-29', '23:00:00', 1, 2, 'Main Stage', 'Completed', 'Called final cast and crew, but directors could add after Wednesday rehearsal. Same night: JTF Presents return of Side Quest (no player list in email) and the final 11pm DeathMatch show. Rick''s Aug 31 recap says it was JTF''s biggest Friday night in total attendance and bar sales across three full shows.', false, 'standard'),
  (291, '2025-08-30', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'BIG SHOW: Called final cast and crew, directors could add after rehearsal. New apprentices Jill and Brett K. worked their first crew duties.', false, 'standard'),
  (292, '2025-09-05', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Day-of email: ''long overdue return of DeathMatch as a full-blown Mainstage 9pm show''. Call time 7:30pm. Same cast as the Sep 2 listing; crew now complete. Jeff replied that he was honored to be in the cast. Replaced earlier listing(s): 2025-09-03T03:32Z ''Your CAST and CREW for this weekend -- Tech Still Needed'' (initial).', false, 'standard'),
  (293, '2025-09-06', '20:30:00', 2, 15, 'Main Stage', 'Completed', 'Director written as ''KIC'' (the Aug 31 email says KC is directing Big Show). Jill and Brett are new cast apprentices doing crew duties. Tech still needed.', false, 'standard'),
  (294, '2025-09-12', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Listing sent Wednesday with spots still open to PLAY in FNL; no later FNL listing found for this weekend, so the final cast may have been larger. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (295, '2025-09-12', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Michelle''s Bday Show: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (296, '2025-09-13', '20:30:00', 2, 12, 'Main Stage', 'Completed', 'Matthew ran the Wednesday Mainstage rehearsal. Same weekend as Michelle''s Birthday Show (JTF Presents); the weekend had full houses. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (297, '2025-09-20', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (298, '2025-09-26', '21:15:00', 1, 12, 'Main Stage', 'Completed', 'Updated FNL cast (''only 57% Columbus Explorers''), replacing the earlier listing the same evening. Crew carried over from the first email. Same night as Diane''s JTF Presents birthday show. Replaced earlier listing(s): 2025-09-23T23:13Z ''THIS week''s CAST and CREW'' (initial).', false, 'standard'),
  (299, '2025-09-26', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Solovela Bday Extravaganza: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (300, '2025-09-27', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: LD''s return to directing (Musical improv). LD sent the day-before lineup only as a PDF attachment ''Cheap Trills - Sept. 27, 2025.pdf'' (thread 19986cd3fd2c66c6, not readable here); dress code black and white for cast and crew. Lucy confirmed on box. Tech still being sought on Sep 26.', false, 'standard'),
  (301, '2025-10-03', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Tito''s Mainstage debut. First Friday DeathMatch.', false, 'standard'),
  (302, '2025-10-04', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'Lili directing.', false, 'standard'),
  (303, '2025-10-10', '21:15:00', 1, 15, 'Main Stage', 'Completed', 'Email calls this the final FNL cast and crew. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (304, '2025-10-11', '20:30:00', 2, 5, 'Main Stage', 'Completed', 'Incomplete listing: still seeking another eligible improviser or two and a tech. LD''s day-of lineup went out only as a PDF attachment ''Big Show - Oct. 11, 2025.pdf'' (thread 199d43b302763777, not readable here), so the full cast is unknown. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (305, '2025-10-17', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Seasonal FNL (''Nightmare on 22nd Street -- Just kidding, it''s just FNL -- or is it?''). Alternates written ''Ferdi (A)'' and ''Brett (A)*'' (asterisk unexplained; Brett could be Brett K. or Brett G.).', false, 'standard'),
  (306, '2025-10-18', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Improvised Horror Movie: Saturday Mainstage slot (Rick U.''s Big Show) featuring the Improvised Horror Movie format Rick U. workshopped at rehearsal.', false, 'standard'),
  (307, '2025-10-24', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'FearProv: Annual FearProv Halloween show. More people wanted to play than could be cast. Mainstage debut of Michael ''birthday boy'' B. (per Oct 26 email). Tech still needed on the day (Oct 24 email); same night as the hip hop class student showcase. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (308, '2025-10-25', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Chills: First ever Cheap Chills (Halloween musical improv). Jill Pavlov''s big Mainstage debut. Attire all black. LD''s day-of lineup went out only as a PDF attachment ''Cheap Chills - Oct. 25, 2025.pdf'' (thread 19a1c673c3be82cd, not readable here). Bar from the theater''s scheduling sheet.', true, 'standard'),
  (309, '2025-10-31', '21:15:00', 1, 4, 'Main Stage', 'Completed', 'Halloween night FNL. Matthew and Diana ran Wednesday rehearsal. ''Brett'' not disambiguated (Brett K. or Brett G.). Bar from the theater''s scheduling sheet.', false, 'standard'),
  (310, '2025-11-01', '20:30:00', 2, 12, 'Main Stage', 'Completed', 'Halloween weekend Saturday. Earlier email said the weekend was short of players. A Nov 1 email ''We need BOX for tonight'' (thread 19a411fa04ccd645, outside fork A''s list) suggests the box assignment changed. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (311, '2025-11-07', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Weekly assignments email. DeathMatch is the cast-only 9pm Mainstage show on the first Friday of each month. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (312, '2025-11-08', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'Day-of: Christoph dropped for a work commitment, leaving four players including Rick M. Crew carried over from the Nov 5 listing. Rick ran a telenovela-style La Ronde; setlist attached as PDF (Big Show Nov 8 2025.pdf). Rick sent show notes Nov 10. Replaced earlier listing(s): 2025-11-05T13:57Z ''This week''s CAST and CREW'' (initial); 2025-11-05T21:47Z ''YOU are in Saturday night''s show CAST and CREW'' (updated).', false, 'standard'),
  (313, '2025-11-14', '21:15:00', 1, 14, 'Main Stage', 'Completed', 'Final: Rick''s day-of list minus Brett, per Ferdi''s 5:00pm reply ("and minus Brett"). Ferdi''s setlist and his show notes (FNL Notes - Nov 14, 2025.pdf) were attachments. Replaced earlier listing(s): 2025-11-11T22:26Z ''THIS week''s CAST and CREW assignments'' (initial); 2025-11-14T21:58Z ''YOU are in tonight''s FNL - Cast and Crew'' (day-of).', false, 'standard'),
  (314, '2025-11-15', '20:30:00', 2, 13, 'Main Stage', 'Completed', 'Sammi directing. Tito''s first Saturday night Mainstage show after completing his 8th crew duty (apprenticeship) on Friday. Christoph''s birthday weekend. No later listing for this show found in this range. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (315, '2025-11-21', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Latest listing: Matthew no longer listed, Box open ("MAYBE YOU???"). Erik Mena back on stage from New York. JTF Presents Harold team also played that night. Ferdi made a poster; Jarrett''s day-of setlist was an attachment (Show Setlist(3).PDF). Replaced earlier listing(s): 2025-11-18T17:18Z ''FNL Cast and FNL and Cheap Trills Crews'' (initial); 2025-11-19T22:37Z ''YOU are in Friday night''s CAST and CREW'' (updated).', false, 'standard'),
  (316, '2025-11-21', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Harold: From the JTF Presents booking sheet (no cast email about it). The sheet also lists ''Alicili'' (Alice or Lili?).', true, 'jtf_presents'),
  (317, '2025-11-22', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'Cheap Trills: Day-of from Rick Urban: "Attention: Rick U, LD, David H, Lili, Jill, Jeff, Libby - CAST"; a 7 person show (lineup PDF attached, "Nov 22 Cheap trills 7 person .pdf"). Thanksgiving-dinner colorful dress theme. Carol (Musical Director) and Vicky (Bar) from the Nov 20 listing were not restated. Replaced earlier listing(s): 2025-11-18T17:18Z ''FNL Cast and FNL and Cheap Trills Crews'' (initial); 2025-11-19T19:34Z ''YOU are in Saturday night''s Cheap Trills Show CAST and CREW'' (updated); 2025-11-21T00:59Z ''Updated CAST and CREW for this weekend - We need Box for Friday now'' (updated). Musical Director (Carol) and Bar (Vicky) carried over from Rick M.''s Nov 20 and Nov 21 listings; the same six players appear in Rick M.''s Nov 21 listing.', false, 'standard'),
  (318, '2025-11-28', '21:15:00', 1, 7, 'Main Stage', 'Completed', 'Thanksgiving weekend. Per the Nov 30 recap the FNL sold out and about 10 seats had to be added; bartenders took home more than in tips across the weekend. No later listing found.', false, 'standard'),
  (319, '2025-11-29', '20:30:00', 2, 15, 'Main Stage', 'Completed', 'KC is listed first without a role label; the email opens "Lili and KC have their casts", so KC is the director. Thanksgiving weekend, described afterwards as an equally festive Big Show. No later listing found.', false, 'standard'),
  (320, '2025-12-05', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: "Jarrett now has six players for the show." Crew carried over from the Dec 3 morning email (Carlos F. moved from maybe-House into the cast). Per the Dec 8 recap this was Annette''s first Mainstage show and DeathMatch "kicked things up to the next level". Replaced earlier listing(s): 2025-12-03T18:50Z ''DeathMatchers Needed -- This Week''s Cast and Crew'' (initial).', false, 'standard'),
  (321, '2025-12-06', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Day-of: Jeff on Bar "and 8pm show, if necessary". Rick U. sent the lineup as an attachment (Big Show Dec 6 (5person).pdf). Replaced earlier listing(s): 2025-12-03T18:50Z ''DeathMatchers Needed -- This Week''s Cast and Crew'' (initial).', false, 'standard'),
  (322, '2025-12-12', '21:15:00', 1, 9, 'Main Stage', 'Completed', 'Richard L. in town for two weeks. JTF Presents slot still open that night. Jorge Berrios added per Rick M.''s Dec 10 email (''now Jorge Berrios playing in FNL this weekend'', thread 19b0aa25a731a197), confirmed by the Dec 15 recap. Box set to TBA because the same Dec 10 email says Box for Friday was just lost (Dom had been listed); who filled it is unknown. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (323, '2025-12-13', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: Day-of: "Xavier can''t make it tonight", so Emanuel moved from House to Box (LD: "you are NOW on box"), and Jeff, on Bar, agreed to cover the 8pm show in the Spotlight. LD''s Dec 12 lineup email (Cheap Trills - Dec. 13, 2025.pdf, attachment only) called it the first Cheap Trills for Libby, Carlos V., and Mike A.; Rick''s Dec 15 recap calls it their Cheap Trills debut. Replaced earlier listing(s): 2025-12-09T21:55Z ''JTF - This Week''s Casts, Crews, and Events'' (initial); 2025-12-12T05:12Z ''YOU are in Saturday night''s Cheap Trill Show - CAST and CREW'' (updated).', false, 'standard'),
  (324, '2025-12-19', '21:15:00', 1, 8, 'Main Stage', 'Completed', 'As many as 15 people were available to play, including Adrian, in town for the weekend. Brett K. added per the Dec 22 recap (''Brett K.''s first Mainstage show on Friday'', thread 19b43e9787570c3e); he was not on the Dec 17 listing.', false, 'standard'),
  (325, '2025-12-19', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Funny Fortunes Show: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (326, '2025-12-20', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Tech still needed at the time of this email. Emanuel, who was on Rick M.''s Dec 16 confirmation, is no longer listed. Rick U.''s day-of lineup (Big show Dec 20 2025 (7person).pdf, attachment only, sent 2025-12-20T20:10Z) went to Alex T., Jeff, Jill, Rich Lopez, Adrian, Brett Kaufman, Ferdi Rodriguez and Omar Gonzalez (Tito); since it was a 7 person show, Ferdi and Tito may have been added and Brett K. may have teched, but this is unconfirmed. Rick U. added about 5 pieces not done before because there was no rehearsal. Replaced earlier listing(s): 2025-12-17T01:51Z ''YOU are in Saturday night''s Big Show'' (initial).', false, 'standard'),
  (327, '2025-12-26', '21:15:00', 1, 12, 'Main Stage', 'Completed', 'Final FNL of 2025. 12 presales by Tuesday morning. Stefany moved from Tech (Dec 22 crew list) into the cast; Tech open. Per the Dec 27 email, more than 50 guests attended even with five presale no-shows (Lucy reported the box office numbers). No day-of listing found in this range. Replaced earlier listing(s): 2025-12-22T02:35Z ''THIS week at JTF and YOU'' (initial).', false, 'standard'),
  (328, '2025-12-27', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'Final Mainstage show of 2025, NYE-themed. Mark Mocahbee''s return; Jorge Berrios guest after his Spanish workshop that afternoon. 15 presales by Tuesday; strong presales, standing room expected. Diana''s day-of lineup (JTF_Lineup_122725.pdf) was an attachment only; its recipients matched this list plus crew, and also included Jill, who is not on this list (possible late add, unconfirmed). Replaced earlier listing(s): 2025-12-22T02:35Z ''THIS week at JTF and YOU'' (initial).', false, 'standard'),
  (329, '2026-01-02', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Email says "our first DeathMatch and Big Show of 2025" (meaning 2026). Jamie on Bar "(and One Hot Hour)". Fourth month in a row with Jarrett leading DeathMatch. Jarrett sent the Jan 2 setlist as an attachment only (Copy of Show Setlist.PDF), "As always, subject to change."', false, 'standard'),
  (330, '2026-01-02', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Doc Doc Goose and Copy/Paste: 9:30pm in the Spotlight; kicks off a busy JTF Presents slate (8 of the next 9 weekends booked). Performers named in the weekly newsletter, not a formal cast list.', true, 'jtf_presents'),
  (331, '2026-01-03', '20:30:00', 2, 6, 'Main Stage', 'Completed', 'First Big Show of 2026, directed by Alex Taylor. Presales more typical than the holiday weekend.', false, 'standard'),
  (332, '2026-01-09', '21:15:00', 1, 2, 'Main Stage', 'Completed', 'Rick M.''s individual ''YOU are in FNL tomorrow night'' email (Thu Jan 8, 2:18 PM EST), sent after Wednesday rehearsal; original message not in mailbox, cast taken from the quote in Ferdi''s reply. Jeff asked to watch over the 8 p.m. One Hot Hour. Ferdi made a show poster titled ''The Friday Bunch''. Rick U.''s day-of lineup is attachment only (''Jan 9 (7person).pdf'' and .xlsx), not readable here. Replaced earlier listing(s): 2026-01-07T05:12Z ''This weekend''s CASTS -- Crew still needed'' (initial); 2026-01-08T22:15Z ''SHAKESPEARE update and revised cast and crews for this weekend'' (updated). Michael B. removed from the cast here because he dropped out the day of the show with a fever (same thread); Rick U.''s lineup file was titled ''7person'', which fits.', false, 'standard'),
  (333, '2026-01-09', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Future Memories with Friends: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (334, '2026-01-10', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'Revised cast and crew. Diana and Dom from the preliminary list no longer listed; Alex T. and Joe added. Replaced earlier listing(s): 2026-01-07T05:12Z ''This weekend''s CASTS -- Crew still needed'' (initial).', false, 'standard'),
  (335, '2026-01-16', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Set cast and crew for the weekend. Jarrett''s day-of lineup (sent Fri Jan 16, ''JTF Setlists Jarrett(4).PDF'') is attachment only, no cast changes stated in text. Dom''s birthday was Saturday Jan 17.', false, 'standard'),
  (336, '2026-01-16', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'SUSS IMPROV: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (337, '2026-01-17', '20:30:00', 2, 15, 'Main Stage', 'Completed', 'BIG SHOW: Set cast and crew for the weekend. Mike A. also listed as Friday FNL tech.', false, 'standard'),
  (338, '2026-01-23', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Day-of: Rick M. wrote ''TONIGHT at JTF I''m directing the 9 p.m. Friday Night Live show'' and named the players joining him. Crew not restated; the Jan 19 listing had Maria (Tech), Amanda (Box), James (House), Jamie (Bar). Replaced earlier listing(s): 2026-01-19T23:28Z ''This Week''s CAST and CREW'' (initial). Crew carried over from the Jan 19 listing (the day-of email did not restate it).', false, 'standard'),
  (339, '2026-01-23', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'The David Magnifico Show: From a ''shameless plug'' in the weekly cast email: The David Magnifico Show with LD and Alex T., JTF Presents, Friday 9:30 p.m. Rick M.''s Jan 23 email calls it LD''s David Magnifico show in the Spotlight at 9:30 p.m. (magic, comedy and improv; first performed a couple of months earlier).', true, 'jtf_presents'),
  (340, '2026-01-24', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'BIG SHOW with Asaf Ronen: Guest Asaf Ronen (touring improviser, director at the Austin Creative Alliance) played after teaching workshops that afternoon. Maria is also listed as Friday FNL tech.', false, 'standard'),
  (341, '2026-01-30', '21:15:00', 1, 15, 'Main Stage', 'Completed', 'Final cast after Wednesday rehearsal, sent the evening of the show. Replaced earlier listing(s): 2026-01-27T04:25Z ''THIS week''s CAST and CREW -- Still need some Crew help'' (initial).', false, 'standard'),
  (342, '2026-01-30', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Bros 2 Men: JTF Presents that night: Bros 2 Men (Val and Michael B.), longtime buddies who had missed chances to play together since Michael completed his fourth apprenticeship duty.', true, 'jtf_presents'),
  (343, '2026-01-30', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Copy Paste: JTF Presents that night: Copy Paste (Alice and Lili), on the same bill as Bros 2 Men.', true, 'jtf_presents'),
  (344, '2026-01-31', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'CHEAP TRILLS: Final cast; Tech still needed as of Friday evening. Carol listed as Musical Director. Replaced earlier listing(s): 2026-01-27T04:25Z ''THIS week''s CAST and CREW -- Still need some Crew help'' (initial).', false, 'standard'),
  (345, '2026-02-06', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: YOU-are-in email, same cast as the weekly listing, adds Jeff on Bar and One Hot Hour. Jarrett replied on show day (2026-02-07T00:15Z) with the setlist as a PDF attachment only (''Copy of Show Setlist.PDF''), not readable here. Replaced earlier listing(s): 2026-02-03T04:01Z ''THIS week''s cast and crew'' (initial).', false, 'standard'),
  (346, '2026-02-06', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Copy Paste: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (347, '2026-02-07', '20:30:00', 2, 14, 'Main Stage', 'Completed', 'BIG SHOW: ''Nothing has changed since the earlier email.'' 16 presells the night before. Ferdi replied on show day with the lineup as PDF attachments only (''BIG SHOW - Backstage.pdf'', ''BIG SHOW - 2.7.26 - FULL.pdf''), not readable here. Replaced earlier listing(s): 2026-02-03T04:01Z ''THIS week''s cast and crew'' (initial).', false, 'standard'),
  (348, '2026-02-13', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Weekly listing, identical to the YOU-are-in email sent about 12 hours earlier. Nearly 30 sales that night per Rick M.''s 2026-02-14 email. Replaced earlier listing(s): 2026-02-10T01:19Z ''YOU are in Friday night''s FNL - CAST and CREW'' (initial).', false, 'standard'),
  (349, '2026-02-14', '20:30:00', 2, 12, 'Main Stage', 'Completed', 'BIG SHOW: Valentine''s Day Saturday. Michael T. making his Big Show debut (Rick M. later: ''No pressure Mr. Tome, on your first Big Show''). Tech still needed at time of listing; Saturday bartender spot reopened on 2026-02-12 (Jocelyn''s Bar slot may have changed). 31 pre-sales that night, biggest weekend crowd of 2026 so far. No later listing found in this range.', false, 'standard'),
  (350, '2026-02-15', '20:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'CLUTCH + FRIENDS: From the JTF Presents booking sheet (no cast email about it). A Sunday show at 2PM.', true, 'jtf_presents'),
  (351, '2026-02-20', '21:15:00', 1, 7, 'Main Stage', 'Completed', 'Day-of email (''Lily''s Friday Night Live''). Box filled by Carlos V.; Carlos F. (VP of Operations) keyholder. Lili sent an ''8 person FNL Feb 20, 2026'' lineup as xlsx/PDF attachments (not readable; 8 matches the director plus 7 listed). Lili''s post-show notes: light audience; Annette hosted Psychic Twins for the first time; Michael B.''s parents attended; Annette called it her first big show; the cast celebrated Tito and Yari. Replaced earlier listing(s): 2026-02-16T23:59Z ''THIS week''s cast and crew'' (initial).', false, 'standard'),
  (352, '2026-02-21', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'BIG SHOW: Weekly listing; no later listing found in this range. Rick M. later called it ''a blast of Olympian proportions''; Brett K.''s parents were in town and saw him play. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (353, '2026-02-22', '20:30:00', 10, 2, 'Main Stage', 'Completed', 'Sketch Writing 2 show: Student class show of Rick Urban''s ''Game of Sketch'' (Sketch Writing 2) class, Sunday at JTF (rehearsal 2-5 p.m.; Rick M. said it started about 7:23 p.m.). Tentative casting is only in the PDF attachment ''Game of Sketch class Show Feb  - 2026.pdf'', not readable here. Body names sketch writers Natasha and Markee and a Sarah; casting could change. Jeff was BCC''d on this email (likely a class member) but his role is unconfirmed.', false, 'standard'),
  (354, '2026-02-27', '21:15:00', 1, 9, 'Main Stage', 'Completed', 'Day-of ''cleaning up the cast list'' email ahead of 7:30 p.m. call time. Replaces the Feb 24 listing. Replaced earlier listing(s): 2026-02-25T00:53Z ''This week''s CAST and CREW'' (initial).', false, 'standard'),
  (355, '2026-02-28', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: ''Cleaning this cast list up ahead of tomorrow night''s Cheap Trills show.'' Replaces the Feb 24 listings. LD sent the show-day lineup on 2026-02-28 as a PDF attachment only (''Cheap Trills - Feb. 28, 2026.pdf''), not readable here; dress code black and white. Jeff replied that he would see everyone that night. Replaced earlier listing(s): 2026-02-25T00:50Z ''YOU are in Saturday night''s Big Show - CAST and CREW'' (initial); 2026-02-25T00:53Z ''This week''s CAST and CREW'' (initial).', false, 'standard'),
  (356, '2026-03-06', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Matt Castellvi listed as (Guest), visiting improviser from Chicago/Boom Chicago. Ferdi is listed twice in the email (he joked about pulling double duty). Packed house. Jarrett got married the night before.', false, 'standard'),
  (357, '2026-03-07', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'Packed house despite Carnavale on the Mile. A later email says Vicky and Jeff were the bartenders this weekend.', false, 'standard'),
  (358, '2026-03-13', '21:15:00', 1, 2, 'Main Stage', 'Completed', 'Replaces the 2026-03-09 initial listing (same cast; Vicky added as Bar).', false, 'standard'),
  (359, '2026-03-13', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Michelle + FRNDZ: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (360, '2026-03-14', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'Pi(e) Day show. Samuel''s first Big Show; Rebecca''s assistant directing debut. Devorah added late. Crew line reads ''Jeff - Bar & 8 p.m. show'' (Jeff also played the 8 p.m. student-eligible show). Rick joked ''we also won an Oscar'' (unclear if Oscar joined). Replaces initial (2026-03-09) and updated (2026-03-11) listings.', false, 'standard'),
  (361, '2026-03-20', '21:15:00', 1, 2, 'Main Stage', 'Completed', 'Itzak''s Mainstage debut; Christine''s crew debut. Listing from the 3/16 preliminary email; Rick Urban''s day-of lineup email (3/20, PDF ''FNL 4 person March 20 2026'') confirms the same six people: Tito, Emanuel, Itzak, Brett K, Christine, Christoph.', false, 'standard'),
  (362, '2026-03-20', '21:30:00', 8, 12, 'Spotlight Room', 'Completed', 'Side Quest 3: From the JTF Presents booking sheet (no cast email about it). The sheet left the players blank; Jeff gave the cast and director (2026-11-09): Matthew directs the group.', true, 'jtf_presents'),
  (363, '2026-03-21', '20:30:00', 2, 5, 'Main Stage', 'Completed', 'Preliminary listing (Tech was ''???'', still needed as of 3/19). LD''s day-of email (3/21) attached the lineup as a PDF only, so the final cast could not be confirmed from the email text. A 3/22 email thanks Alex T. for stepping up to tech (Dave R. also offered).', false, 'standard'),
  (364, '2026-03-22', '20:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'CLUTCH + FRIENDS: From the JTF Presents booking sheet (no cast email about it). A Sunday show at 2PM.', true, 'jtf_presents'),
  (365, '2026-03-27', '21:15:00', 1, 13, 'Main Stage', 'Completed', 'Rick dubbed it ''Three Sams and an ID'' (Sammi, Samantha, Samuel plus Itzak and Diana).', false, 'standard'),
  (366, '2026-03-28', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: Monthly musical improv show.', false, 'standard'),
  (367, '2026-04-03', '21:15:00', 9, 1, 'Main Stage', 'Completed', 'DeathMatch: First DeathMatch in a long streak not run by Jarrett; Rick M. stepped in to ''don the pinstripes''. Visiting improviser Asaf Ronen was to play in either this show or the Big Show that weekend (not confirmed in email).', false, 'standard'),
  (368, '2026-04-04', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'Email says ''Michael B. and Mike A. will cover tech and box''; Jamie on Bar and the 8 p.m. student show. Asaf Ronen was expected to play in DeathMatch or this show (not confirmed).', false, 'standard'),
  (369, '2026-04-10', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Late 9 p.m. FNL (8:30 call) because an Improv 2 student show took the Mainstage at 7:30. Annette''s eighth and final apprentice crew duty.', false, 'standard'),
  (370, '2026-04-11', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'Preliminary; Lili might add cast after Wednesday rehearsal and Tech was still needed. (The 4/5 email had called it ''Matthew''s Big Show''.)', false, 'standard'),
  (371, '2026-04-17', '21:15:00', 1, 15, 'Main Stage', 'Completed', 'Tech still needed as of the email. Per a 4/19 email the bartender (Vicky was listed) could not make it, so Christine covered both Box and Bar.', false, 'standard'),
  (372, '2026-04-17', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Together/By Myself: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (373, '2026-04-18', '20:30:00', 11, 4, 'Main Stage', 'Completed', 'IMPROUD: Return of IMPROUD (celebrating LGBTQ+ cast and allies) in the Big Show slot; co-directed by Diana and Matthew.', true, 'standard'),
  (374, '2026-04-24', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'No Wednesday FNL rehearsal that week. Day-of update: Brett K. in, Kim out, Jeff added as bartender. Replaces the 2026-04-20 preliminary listing (which had Kim). Jarrett sent a setlist PDF that evening.', false, 'standard'),
  (375, '2026-04-24', '21:30:00', 7, 4, 'Main Stage', 'Completed', '¡Dale! Impro: Premiere of ¡Dale! Impro, the new monthly Spanish/Spanglish show, 9:30 p.m. in the Spotlight (JTF Presents slot). Email says Box, House and Bar same as FNL (Stefany, Dom, Jeff per the FNL day-of update).', false, 'standard'),
  (376, '2026-04-25', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: Three cast changes and a bartender change from the 2026-04-20 preliminary (which had Carlos V., Ferdi, Lili, Maria, Matthew, Jill; Jamie on Bar). Musical rehearsal Wednesday with LD and Carol. LD sent a PDF lineup the night before.', false, 'standard'),
  (377, '2026-05-01', '21:15:00', 9, 5, 'Main Stage', 'Completed', 'DeathMatch: Teams: Red Team Stefany & Oscar; Blue Team Emanuel & Devorah. LD stepped up to direct because Jarrett was doing the disco JTF Presents show. The 4/28 preliminary (headed ''FNL'') listed LD with Devorah, Emanuel, Stefany, Christine; LD''s day-of email replaced Christine with Oscar. Crew per preliminary: ''Alex H. or Yvette'' on Tech and Box (''Team Haq''), Rebecca on Bar.', false, 'standard'),
  (378, '2026-05-01', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Just the Disco: An Improv Musical: The Not So Furious Five''s first show and Jeff''s Just the Funny directorial debut: the theater''s best singers in a musical improv set in a 70s disco, with a door prize for disco outfits. Jeff directs the troupe and plays.', true, 'jtf_presents'),
  (379, '2026-05-02', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Sketch and improv Big Show (with the iconic Just The News segment). Markee and Mike A. listed as ''(Sketch)'' only. Itzak''s final apprentice crew duty. Bar still open. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (380, '2026-05-08', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Val grabbed the open Tech spot. Replaces the 2026-05-05 listing (Tech TBA). ''Chrstine'' as written (Christine).', false, 'standard'),
  (381, '2026-05-09', '20:30:00', 2, 14, 'Main Stage', 'Completed', 'Ferdi''s ''Big MAMA Show'', a Mother''s Day themed Big Show. Itzak''s Big Show debut. Carlos V. added on Box versus the 2026-05-05 listing, which it replaces. Cast praised it afterward as extraordinary.', false, 'standard'),
  (382, '2026-05-15', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Alex T. added and Christoph took Box versus the 2026-05-12 listing, which it replaces. Rebecca''s ''Mami Knows Best'' was the JTF Presents show that night.', false, 'standard'),
  (383, '2026-05-16', '20:30:00', 2, 5, 'Main Stage', 'Completed', 'Cast unchanged from the 2026-05-12 listing; Alex T. added on Tech; Box still needed. Replaces the earlier listing.', false, 'standard'),
  (384, '2026-05-17', '20:30:00', 11, NULL, 'Main Stage', 'Completed', 'Improv and magic show for kids: Sold-out Sunday improv and magic show for kids, mentioned in passing (no formal cast list).', true, 'standard'),
  (385, '2026-05-22', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Memorial Day weekend. New apprentices Bryan and Dunia on crew.', false, 'standard'),
  (386, '2026-05-23', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'About a dozen people were available and not everyone was cast. New apprentices Arnold and Jacob on crew.', false, 'standard'),
  (387, '2026-05-29', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Replaces the 2026-05-26 preliminary (same cast; Alice, Kim, Mike A. and Samuel had the option to audition for Dale Impro; Shari had been listed on Tech and Dunia on House/Tech). Per a 5/29 day-of email, Dunia (listed as FNL tech) moved to tech Dale Impro and a FNL tech was still needed.', false, 'standard'),
  (388, '2026-05-29', '21:30:00', 7, 4, 'Main Stage', 'Completed', 'Dale Impro: Second ¡Dale! Impro (Spanish), Friday 9:30 p.m. in the Spotlight. A Spanish-fluent tech was still needed. Replaces the 2026-05-26 preliminary (Diana, Tito, Spanish cast TBA). Dunia (the FNL tech) covered the Dale tech per a 5/29 email.', false, 'standard'),
  (389, '2026-05-30', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'Cheap Trills: Rick U. directing the monthly musical improv show. Replaces the 2026-05-26 preliminary (same cast; Lucy had been Box and Audrey House).', false, 'standard'),
  (390, '2026-06-05', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Jarrett back directing DeathMatch. Four apprentices making their Mainstage debut (per email; likely Bryan, Dunia, Jacob, plus Christine''s first Mainstage show). Bar listed as ''Rebecca & Paris''.', false, 'standard'),
  (391, '2026-06-06', '20:30:00', 2, 4, 'Main Stage', 'Completed', 'A 6/8 recap credits ''Diana''s Big Show'' (large crowd), so Diana is listed as director; the 6/2 preliminary had ''Rick M. (Director?)'' and ''Ferdi (Director?)''. Directors listed with question marks (''Rick M. (Director?)'', ''Ferdi (Director?)''). Liz Miele did four stand-up shows that weekend in the Spotlight. Bar listed as ''Rebecca & Paris''.', false, 'standard'),
  (392, '2026-06-12', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Michelle added day-of (to plug her new stand-up class), making a cast of 8 including Rick M. and Dom. Pieces: 4 Corners, Expando, The Event as a Third Date, Speed Dating, The Unusuals. Dom led a rehearsal split. Replaces the 2026-06-08 listing (which had no Michelle or bartender).', false, 'standard'),
  (393, '2026-06-12', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'JTF Presents: Mentioned in passing: ''Lili, Carlos F., Shari, and Alice on the JTF Presents stage tonight''. 16 people on the Mainstage that weekend.', true, 'jtf_presents'),
  (394, '2026-06-13', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'More people wanted to play than the 15 spots that weekend. Sketch was dropped from this Big Show. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (395, '2026-06-19', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'FNL with JD Walsh: Guest JD Walsh played. Audrey''s Mainstage debut. A 6/16 follow-up said there was ''shuffling'' on Friday and asked for Tech and Box help, so crew may have changed. Jarrett sent a setlist PDF day-of.', false, 'standard'),
  (396, '2026-06-19', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'June Bugs: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (397, '2026-06-20', '20:30:00', 2, 7, 'Main Stage', 'Completed', 'Verified via Casting Call & Gmail', false, 'standard'),
  (398, '2026-06-26', '21:15:00', 1, 2, 'Main Stage', 'Completed', 'Cast was light; replaces the 2026-06-23 partial listing (Dave R., Kim ''(Cast or maybe tech)'', Tito, no director named). Rick U. listed as both director and tech.', false, 'standard'),
  (399, '2026-06-26', '21:30:00', 7, 4, 'Main Stage', 'Completed', 'Dale Impro: Sold out (21 pre-sales by Monday, then standing room only); an extra House/Box helper was requested day-of. Replaces the 2026-06-23 listing (Tech ''Lili (or Kim)'').', false, 'standard'),
  (400, '2026-06-27', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: Carol on piano. Dress code black and white. At least four people who wanted in were not cast. Devorah picked up the Box spot that opened (per 6/26 email). Replaces the 2026-06-23 listing (Lucy Box, Paris Bar). LD sent a PDF lineup the night before.', false, 'standard'),
  (401, '2026-07-03', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Rare one-show weekend (closed July 4), so Jarrett ran a 5 vs. 5 DeathMatch. Arnold''s Mainstage debut. Jarrett''s day-of teams: Red = Alice, Bryan, Jeff, Lili, Samuel; other team = Arnold, Dunia, Ferdi, Jocelyn, Tito. Jarrett also sent a setlist PDF.', false, 'standard'),
  (402, '2026-07-10', '21:15:00', 1, 16, 'Main Stage', 'Completed', 'Dom''s directing debut; Mark''s homecoming.', false, 'standard'),
  (403, '2026-07-10', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Christmas in July: An Improv Musical: The Not So Furious Five''s second show, Friday 9:30 p.m. (the troupe''s May meeting had planned it for July 17). No email lists the night''s cast, so this is the troupe as invited to that meeting.', true, 'jtf_presents'),
  (404, '2026-07-11', '20:30:00', 2, 12, 'Main Stage', 'Completed', 'Replaces the 2026-07-06 listing (same cast; crew changed from Dunia Tech, Bryan Box, Jamie Bar).', false, 'standard'),
  (405, '2026-07-17', '21:15:00', 1, 14, 'Main Stage', 'Completed', 'FNL was held in the Spotlight. Rick U. had been listed as Tech but was sent to tech the stand-up show, so a light tech was still needed the day of the show.', false, 'standard'),
  (406, '2026-07-18', '20:30:00', 2, 17, 'Main Stage', 'Completed', 'Henry''s directorial debut; Audrey''s Big Show debut. Henry''s day-of lineup was sent only as an image/PDF titled ''Big show 7 person'', consistent with Henry plus these six. ''Lily'' as written (could be Lili or Lily L.). A UFC fighter was reportedly in the audience that weekend.', false, 'standard'),
  (407, '2026-07-24', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Cast still open as of the email (eligible players were told to contact Jarrett). Cheap Trills drew twice as many interested players as spots.', false, 'standard'),
  (408, '2026-07-24', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Doc Doc Goose / Copy Paste: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (409, '2026-07-25', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: Twice as many people wanted in as there was room. Attire all black. ''Musical Day in the Life'' was a surprise tribute to music director Carol for her birthday, with her husband Mark joining LD on stage; cake after. LD''s day-of lineup (PDF) went to the six cast plus Jacob and Lucy, so Jacob probably filled the open Tech spot (he logged two crew duties that weekend). The 7/21 email mislabeled this as ''BIG SHOW CAST and CREW''.', false, 'standard'),
  (410, '2026-07-31', '21:15:00', 1, 9, 'Main Stage', 'Completed', 'Packed house. 25 people on stage across the weekend''s three shows; nearly a half-dozen interested players did not make it. Oscar''s day-of lineup was an attached spreadsheet only. Box, House and Bar were listed as shared ''Friday crew'' with Dale Impro.', false, 'standard'),
  (411, '2026-07-31', '21:30:00', 7, 4, 'Main Stage', 'Completed', 'Dale Impro: In the Spotlight with a DeathMatch-esque format; packed house. Pryscila was listed as Dale tech but a day-of email asked for a tech, so Tech is TBA. ''Inrgid'' as written (Ingrid). Box/House/Bar shared Friday crew.', false, 'standard'),
  (412, '2026-08-01', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Sketchy Big Show: Part sketch, part improv Big Show with a Just The News segment. Samuel and Arnold were bumped from crew to the following week.', false, 'standard'),
  (413, '2026-08-07', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: First weekend with JTF''s new logo and website. Many cast members away at the Countdown Festival. Rick re-sent the cast email directly to the active cast because @justthefunny.com mail bounced during the domain transfer. ''Itzakh'' as written (Itzak).', false, 'standard'),
  (414, '2026-08-08', '20:30:00', 2, 14, 'Main Stage', 'Completed', 'First weekend with the new logo and website.', false, 'standard'),
  (415, '2026-08-14', '21:15:00', 1, 4, 'Main Stage', 'Completed', 'From the theater''s scheduling sheet: no cast email for this night reached Jeff, so the cast is not known.', false, 'standard'),
  (416, '2026-08-14', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Show + Tell: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (417, '2026-08-15', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'Secrets-themed Big Show (Six Secrets, La Ronde, The Event built from audience secrets). Mike A. was added day-of to open with Michael T. after both shone at the previous night''s Hip Hop grad show; the 8/11 listing (which it replaces) did not include him.', false, 'standard'),
  (418, '2026-08-21', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Rick sent the setlist PDF day-of with no cast changes. ''Michale T.'' as written (Michael T.).', false, 'standard'),
  (419, '2026-08-21', '21:30:00', 7, 4, 'Main Stage', 'Completed', '¡DALE!: Spanish improv show (Dale Impro). More than 30 JTF cast members on stage that weekend.', false, 'standard'),
  (420, '2026-08-22', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'Arnold''s 8th and final apprentice crew duty. Same listing in the 8/18 ''YOU are in'' email and the ''Updated'' cast email.', false, 'standard'),
  (421, '2026-08-28', '21:15:00', 1, 16, 'Main Stage', 'Completed', 'Samuel''s final JTF performance before moving to France (listed ''Samuel - Of course''). More than 70 guests on the Mainstage, possibly the largest combined crowd in years with Michelle''s stand-up showcase in the Spotlight.', false, 'standard'),
  (422, '2026-08-28', '23:00:00', 11, NULL, 'Main Stage', 'Completed', 'Encore: Samuel''s farewell: An 11 p.m. encore for Samuel to play one final long-form piece of his choice with eligible cast not in FNL. Michelle listed ''(If the stand-up showcase is over by then)''; Maria and Markee listed with question marks (''Maria?'', ''Markee?''), so they are put under alternates as tentative.', true, 'standard'),
  (423, '2026-08-29', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Trills: About a dozen players were interested in each show that weekend. LD''s day-of lineup was a PDF only.', false, 'standard'),
  (424, '2026-09-04', '21:15:00', 9, 15, 'Main Stage', 'Completed', 'DeathMatch: Special CELEBRITY DeathMatch (impressions, props optional). Christine''s last show. KC''s teams: TEAM RED Christine (Captain), Alice, Rick, Jeff; TEAM BLUE Lili (Captain), Matthew, Mike, Jacob. Christine also got a 20 to 30 minute long-form Encore afterward run by Diana, open to cast, apprentices, Dale cast and crew. Same cast in the 9/1 cast email and the 9/2 ''YOU are in'' email.', false, 'standard'),
  (425, '2026-09-05', '20:30:00', 2, 1, 'Main Stage', 'Completed', 'Arnold''s first Saturday night Mainstage show. Alex T. picked up Tech and Jeff picked up Bar, replacing the 9/1 listing (TBA Tech, Paris Bar). Setlist PDF sent day-of.', false, 'standard'),
  (426, '2026-09-11', '21:15:00', 1, 12, 'Main Stage', 'Completed', 'Matthew ran the Mainstage rehearsal. A 9/10 note said crews were complete for the weekend but did not name the second Tech/Box person. David Magnifico had the JTF Presents slot. Same as the 9/7 listing.', false, 'standard'),
  (427, '2026-09-11', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'David Magnifico: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (428, '2026-09-12', '20:30:00', 2, NULL, 'Main Stage', 'Completed', 'No director named in the listing (''half of the available players are directors''). Packed houses on both stages; an extra House was requested day-of. Crews were reported complete on 9/10 but names were not given.', false, 'standard'),
  (429, '2026-09-18', '21:15:00', 1, 4, 'Main Stage', 'Completed', 'Partial cast; the email said FNL still had a lot of room. No later FNL listing found. Rebecca hosted the ''Show and Tell'' JTF Presents show that night (standing room expected). Bar from the theater''s scheduling sheet.', false, 'standard'),
  (430, '2026-09-18', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'Show + Tell: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (431, '2026-09-19', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'A Sketchy Big Show: Big Show with sketches mixed into the improv, including the Just The News segment. Replaces the 9/14 listing (Tech and Box TBA).', false, 'standard'),
  (432, '2026-09-25', '21:15:00', 1, 16, 'Main Stage', 'Completed', 'Dom might add a player or two at Wednesday rehearsal. Already 20 presales; a rowdy 22-person birthday party attended.', false, 'standard'),
  (433, '2026-09-25', '21:30:00', 7, 4, 'Main Stage', 'Completed', 'Dale Impro: Another packed Dale Impro performance.', false, 'standard'),
  (434, '2026-09-26', '20:30:00', 3, 2, 'Main Stage', 'Completed', 'Cheap Trills: About a dozen people were available and could not all be cast.', false, 'standard'),
  (435, '2026-10-02', '21:15:00', 9, 14, 'Main Stage', 'Completed', 'DeathMatch Royale: ''Itazk'' as written (Itzak).', false, 'standard'),
  (436, '2026-10-03', '20:30:00', 2, 3, 'Main Stage', 'Completed', 'Verified via Casting Call & Gmail', false, 'standard'),
  (437, '2026-10-09', '21:15:00', 1, 9, 'Main Stage', 'Completed', 'Michael B. completed his eighth crew duty (about 10:58 p.m.) to become a full cast member. About a half-dozen interested players did not make it. Rick M. later praised Oscar for casting a wider net; the audience loved the show.', false, 'standard'),
  (438, '2026-10-10', '20:30:00', 2, 18, 'Main Stage', 'Completed', 'Stefany''s directorial debut. Bar listed as ''Rebecca (maybe)''.', false, 'standard'),
  (439, '2026-10-16', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'Tech still needed as of 10/14. Michelle''s stand-up class showcase was the same night. A follow-up email mentions the debut of ''Christopher Walken Dead'' that Friday.', false, 'standard'),
  (440, '2026-10-17', '20:30:00', 2, 17, 'Main Stage', 'Completed', 'Henry''s second time directing. The show introduced ''Professor Daddy'' into the cast vernacular.', false, 'standard'),
  (441, '2026-10-23', '21:15:00', 1, 3, 'Main Stage', 'Completed', 'Verified via Casting Call & Gmail', false, 'standard'),
  (442, '2026-10-23', '21:30:00', 8, NULL, 'Spotlight Room', 'Completed', 'This Yap Could''ve Been an Email: Mentioned in passing: ''Gigi, Isa, and Sam will have a coven of JTFers doing This Yap Could''ve Been an Email for JTF Presents.'' Full cast not listed.', true, 'jtf_presents'),
  (443, '2026-10-24', '20:30:00', 3, 5, 'Main Stage', 'Completed', 'Cheap Chills: Annual Halloween musical improv show (moved from Oct. 31). The listing also names LD a second time in the cast under himself as director; he is counted only as director here. Dress code all black. LD''s day-of lineup was a PDF only. Nine people had expressed interest.', true, 'standard'),
  (444, '2026-10-30', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'FearProv: Halloween-themed FNL. No alternates cast; everyone expected at the dedicated Wednesday rehearsal. Tech and bartender still needed as of 10/27. Cat confirmed on Box (one crew duty from Friday-night eligibility). Bar from the theater''s scheduling sheet.', false, 'standard'),
  (445, '2026-10-30', '21:30:00', 7, 4, 'Main Stage', 'Completed', 'Dale Impro: October ¡Dale! Impro. Tech was the top crew need as of 10/27.', false, 'standard'),
  (446, '2026-10-31', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'Improvised Horror Movie: Halloween night Big Show themed as an improvised horror movie. Jonathan (returning) took Box per the 10/27 follow-up. Bar from the theater''s scheduling sheet.', false, 'standard'),
  (447, '2026-11-06', '21:15:00', 9, 3, 'Main Stage', 'Completed', 'DeathMatch: Listed under the ''FNL'' heading in Rick''s cast email, but it was a Jarrett DeathMatch (subject of Jarrett''s email: ''Fnl Deathmatch Nov 6''). Day-of teams: Red = Lili, Jeff, Brett; Blue = Dom, Audrey, Emanuel. Tech and Box still open as of 11/2.', false, 'standard'),
  (448, '2026-11-07', '20:30:00', 2, 5, 'Main Stage', 'Completed', 'Carlos Vaca''s 50th show (Rick linked a ''5-0'' video next to his name). LD also appears a second time in the cast list under himself as director; counted once as director. Packed house expected. LD''s day-of lineup was a PDF only. (An Oct. 14 email had said Dom would direct Nov. 7.)', false, 'standard'),
  (449, '2026-11-13', '21:15:00', 1, 1, 'Main Stage', 'Completed', 'FNL (FAA cold open; verified via Nov 10 & Nov 14 Gmail)', false, 'standard'),
  (450, '2026-11-13', '21:30:00', 8, 12, 'Spotlight Room', 'Completed', 'Side Quest 4: From the JTF Presents booking sheet (no cast email about it). Jeff gave the whole lineup (2026-11-09), adding Jonathan F. and Matthew, who directs the group.', true, 'jtf_presents'),
  (451, '2026-11-14', '20:30:00', 2, 2, 'Main Stage', 'Completed', 'A Sketchy Big Show (verified via Nov 10 & Nov 14 Gmail)', false, 'standard'),
  (452, '2026-11-20', '21:15:00', 1, 2, 'Main Stage', 'Scheduled', 'FNL (verified via Nov 17 Gmail)', false, 'standard'),
  (453, '2026-11-20', '21:30:00', 8, NULL, 'Spotlight Room', 'Scheduled', 'Michelle + FRNDZ: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (454, '2026-11-21', '20:30:00', 3, 12, 'Main Stage', 'Scheduled', 'Cheap Trills (Carol Musical Director; verified via Nov 17 Gmail)', false, 'standard'),
  (455, '2026-11-27', '21:30:00', 7, NULL, 'Main Stage', 'Scheduled', 'Dale Impro: From the JTF Presents booking sheet (no cast email about it).', false, 'standard'),
  (456, '2026-12-04', '21:30:00', 8, NULL, 'Spotlight Room', 'Scheduled', 'ALL CAPS Holiday Special: From the JTF Presents booking sheet (no cast email about it). Players not all listed on the sheet.', true, 'jtf_presents'),
  (457, '2026-12-11', '21:30:00', 8, NULL, 'Spotlight Room', 'Scheduled', 'Rebecca and friends: From the JTF Presents booking sheet (no cast email about it).', true, 'jtf_presents'),
  (458, '2026-12-18', '21:30:00', 7, NULL, 'Main Stage', 'Scheduled', 'Dale Impro: From the JTF Presents booking sheet (no cast email about it). To be confirmed.', false, 'standard')
ON CONFLICT (show_id) DO UPDATE SET
  show_date = EXCLUDED.show_date,
  show_time = EXCLUDED.show_time,
  show_type_id = EXCLUDED.show_type_id,
  director_id = EXCLUDED.director_id,
  venue = EXCLUDED.venue,
  status = EXCLUDED.status,
  notes = EXCLUDED.notes,
  is_special_event = EXCLUDED.is_special_event,
  program_category = EXCLUDED.program_category;

SELECT setval(pg_get_serial_sequence('public.show_information', 'show_id'), (SELECT MAX(show_id) FROM public.show_information), true);

